window.GL = window.GL || {};

// Données locales : population, langues, monnaie, résumé historique
// Sources : données générales connues, résumés rédigés manuellement.
GL.COUNTRY_DETAILS = {

  // ===== AFRIQUE =====
  "dz": { population: "46 millions", languages: "Arabe, Berbère (tamazight)", currency: "Dinar algérien (DZD)", summary: "Colonisée par la France en 1830, l'Algérie obtient son indépendance en 1962 après une guerre de libération de huit ans particulièrement meurtrière. Deuxième plus grand pays d'Afrique, son territoire est recouvert à 80 % par le Sahara. Elle connaît une grave crise interne dans les années 1990 (décennie noire) avant de retrouver une stabilité relative grâce aux revenus pétroliers." },
  "ao": { population: "36 millions", languages: "Portugais", currency: "Kwanza (AOA)", summary: "Ancienne colonie portugaise indépendante depuis 1975, l'Angola est immédiatement plongée dans une guerre civile dévastatrice qui dure 27 ans (1975–2002), opposant le MPLA au soutien soviétique et l'UNITA soutenu par les États-Unis et l'Afrique du Sud. Richement dotée en pétrole et en diamants, elle se reconstruit rapidement après la paix, mais les inégalités restent criantes." },
  "bj": { population: "14 millions", languages: "Français, Fon, Yoruba", currency: "Franc CFA (XOF)", summary: "Berceau du puissant royaume de Dahomey (XVIIe–XIXe siècle), connu pour ses armées de femmes guerrières les Agojie. Premier pays africain à avoir réussi une transition démocratique pacifique en 1991. Ses côtes ont été l'un des principaux points d'embarquement de la traite négrière atlantique." },
  "bw": { population: "2,7 millions", languages: "Setswana, Anglais", currency: "Pula (BWP)", summary: "Indépendant en 1966, le Botswana était l'un des pays les plus pauvres du monde ; la découverte de diamants l'a transformé en un État à revenu intermédiaire en quelques décennies, devenant un modèle de bonne gouvernance en Afrique. Il abrite le delta de l'Okavango, classé au patrimoine mondial de l'UNESCO, et l'une des plus grandes densités d'éléphants au monde." },
  "bf": { population: "22 millions", languages: "Français, Mooré, Dioula", currency: "Franc CFA (XOF)", summary: "Anciennement Haute-Volta, rebaptisé Burkina Faso (« pays des hommes intègres ») en 1984 par le président révolutionnaire Thomas Sankara, figure panafricaine assassinée en 1987. Indépendant depuis 1960, le pays a connu de nombreux coups d'État et fait face depuis les années 2010 à une grave insurrection jihadiste dans sa région du Sahel." },
  "bi": { population: "13 millions", languages: "Kirundi, Français, Anglais", currency: "Franc burundais (BIF)", summary: "L'un des pays les plus densément peuplés et les plus pauvres d'Afrique. Depuis son indépendance en 1962, le Burundi a subi des guerres civiles et tensions ethniques récurrentes entre Hutus et Tutsis, culminant dans les années 1990. La capitale a été déplacée de Bujumbura à Gitega en 2019." },
  "cm": { population: "28 millions", languages: "Français, Anglais", currency: "Franc CFA (XAF)", summary: "Surnommé l'« Afrique en miniature » pour son extraordinaire diversité géographique et culturelle (forêts, savanes, montagnes, côtes). Ancienne colonie franco-britannique indépendante depuis 1960, il est gouverné par Paul Biya depuis 1982 — l'un des plus longs règnes présidentiels au monde. Une crise anglophone sévit depuis 2016 dans les régions occidentales." },
  "cv": { population: "560 000", languages: "Portugais, Créole cap-verdien", currency: "Escudo cap-verdien (CVE)", summary: "Archipel de dix îles découvert et colonisé par les Portugais au XVe siècle, sans population autochtone. Plaque tournante de la traite négrière transatlantique, il accède à l'indépendance en 1975. Aujourd'hui reconnu pour sa stabilité démocratique exemplaire sur le continent africain et pour sa musique, la morna, portée mondialement par Cesária Évora." },
  "cf": { population: "5,5 millions", languages: "Français, Sango", currency: "Franc CFA (XAF)", summary: "Richement dotée en diamants, or et uranium, la République Centrafricaine figure paradoxalement parmi les pays les plus pauvres du monde. Depuis son indépendance en 1960, elle subit des décennies de dictatures, coups d'État et guerres civiles. Une grave crise humanitaire perdure depuis 2012 avec des groupes armés contrôlant une grande partie du territoire." },
  "td": { population: "18 millions", languages: "Arabe, Français", currency: "Franc CFA (XAF)", summary: "Enclavé au cœur de l'Afrique, le Tchad est le point de rencontre des cultures arabes et subsahariennes. Des fossiles humains vieux de 7 millions d'années (Toumaï) y ont été découverts, en faisant l'un des berceaux potentiels de l'humanité. Indépendant depuis 1960, il est en proie à une instabilité chronique aggravée par la présence de groupes jihadistes à sa frontière nord." },
  "km": { population: "900 000", languages: "Comorien (Shikomori), Arabe, Français", currency: "Franc comorien (KMF)", summary: "Archipel volcanique de l'océan Indien indépendant depuis 1975, les Comores détiennent le triste record du plus grand nombre de coups d'État par habitant au monde, avec plus de 20 putschs ou tentatives depuis l'indépendance. L'île de Mayotte, revendiquée par les Comores, est restée française et est aujourd'hui un département d'outre-mer." },
  "cd": { population: "100 millions", languages: "Français, Lingala, Swahili, Kikongo, Tshiluba", currency: "Franc congolais (CDF)", summary: "Deuxième plus grand pays d'Afrique et doté de ressources naturelles colossales (cobalt, coltan, or, diamants), la RDC est pourtant l'un des pays les plus pauvres du monde. Après 32 ans de dictature sous Mobutu Sese Seko (1965–1997), le pays sombre dans des guerres dévastatrices à l'est qui font des millions de victimes. Le cobalt congolais est indispensable aux batteries des appareils électroniques mondiaux." },
  "cg": { population: "6 millions", languages: "Français, Lingala, Kituba", currency: "Franc CFA (XAF)", summary: "Ancienne colonie française indépendante depuis 1960, la République du Congo (Congo-Brazzaville) a alterné régimes marxistes et démocratie fragile. Son économie repose très largement sur le pétrole. Elle partage avec la RDC la plus grande forêt tropicale après l'Amazonie." },
  "ci": { population: "27 millions", languages: "Français, Dioula", currency: "Franc CFA (XOF)", summary: "Premier producteur mondial de cacao, la Côte d'Ivoire est le moteur économique de l'Afrique de l'Ouest. Longtemps considérée comme un modèle de stabilité sous Houphouët-Boigny, elle bascule dans une crise politico-militaire de 2002 à 2011 qui divise le pays en deux. Yamoussoukro, capitale officielle, abrite la plus grande basilique du monde (inspirée de Saint-Pierre de Rome)." },
  "dj": { population: "1,1 million", languages: "Arabe, Français, Somali, Afar", currency: "Franc djiboutien (DJF)", summary: "Petit pays stratégique à l'entrée de la mer Rouge, Djibouti est l'un des points de passage les plus importants du commerce maritime mondial. Indépendant depuis 1977, il accueille simultanément des bases militaires française, américaine, japonaise et chinoise. C'est le seul pays au monde où des soldats de ces quatre nations cohabitent." },
  "eg": { population: "105 millions", languages: "Arabe", currency: "Livre égyptienne (EGP)", summary: "Berceau de l'une des plus anciennes et brillantes civilisations du monde (3000 av. J.-C.), avec les pyramides de Gizeh, le Sphinx et les temples de Louxor. Le canal de Suez, inauguré en 1869, est une artère vitale du commerce mondial. En 2011, la révolution de la place Tahrir renverse Hosni Moubarak après 30 ans de pouvoir." },
  "gq": { population: "1,5 million", languages: "Espagnol, Français, Portugais", currency: "Franc CFA (XAF)", summary: "Seul pays hispanophone d'Afrique subsaharienne, la Guinée équatoriale est aussi le plus petit pays du continent. La découverte de pétrole dans les années 1990 en fait l'un des pays africains au PIB par habitant le plus élevé, mais la richesse reste concentrée dans les mains de la famille au pouvoir depuis 1979." },
  "er": { population: "3,5 millions", languages: "Tigrigna, Arabe, Anglais", currency: "Nakfa (ERN)", summary: "L'Érythrée obtient son indépendance de l'Éthiopie en 1993 après 30 ans de guerre de libération. Souvent qualifiée de « Corée du Nord de l'Afrique » pour son régime autoritaire, le service militaire y est illimité et le pays est l'un des plus fermés et des plus pauvres du monde, provoquant un exode massif de sa population." },
  "sz": { population: "1,2 million", languages: "Swati, Anglais", currency: "Lilangeni (SZL)", summary: "Ancien Swaziland rebaptisé Eswatini en 2018, c'est la dernière monarchie absolue d'Afrique subsaharienne, dirigée par le roi Mswati III. Enclavé entre l'Afrique du Sud et le Mozambique, il souffre de l'un des taux de prévalence du VIH/SIDA les plus élevés au monde (environ 27 %)." },
  "et": { population: "126 millions", languages: "Amharique (et plus de 80 autres langues)", currency: "Birr éthiopien (ETB)", summary: "L'Éthiopie est l'un des pays les plus anciens du monde, jamais colonisé hormis une brève occupation italienne (1936–1941). Elle est le berceau probable de l'humanité moderne, où fut découvert en 1974 le fossile de Lucy (3,2 millions d'années). Addis-Abeba abrite le siège de l'Union africaine, et l'Éthiopie est la deuxième nation la plus peuplée du continent." },
  "ga": { population: "2,4 millions", languages: "Français, Fang", currency: "Franc CFA (XAF)", summary: "Le Gabon est l'un des pays les plus boisés d'Afrique, avec des forêts tropicales couvrant 88 % de son territoire et une biodiversité exceptionnelle (gorilles, éléphants de forêt). Richement doté en pétrole, il jouit d'un niveau de vie parmi les plus élevés d'Afrique subsaharienne. Albert Schweitzer y fonda son célèbre hôpital à Lambaréné en 1913." },
  "gm": { population: "2,7 millions", languages: "Anglais, Mandingue, Wolof", currency: "Dalasi (GMD)", summary: "Plus petit pays continental d'Afrique, la Gambie est entièrement enclavée dans le Sénégal, ne possédant qu'une façade de 80 km sur l'Atlantique. Indépendante depuis 1965, elle a subi la dictature de Yahya Jammeh pendant 22 ans avant que des élections démocratiques ne le chassent du pouvoir en 2016." },
  "gh": { population: "33 millions", languages: "Anglais, Akan, Ewe", currency: "Cedi ghanéen (GHS)", summary: "Le Ghana est le premier pays d'Afrique subsaharienne à avoir accédé à l'indépendance en 1957, sous la direction du panafricaniste Kwame Nkrumah. Il abrite des châteaux négriers sur sa côte (classés au patrimoine de l'UNESCO) qui furent des points de départ de la traite atlantique. Aujourd'hui reconnu pour sa démocratie stable et sa croissance économique soutenue." },
  "gn": { population: "14 millions", languages: "Français, Pular, Malinké", currency: "Franc guinéen (GNF)", summary: "La Guinée détient d'immenses réserves de bauxite (aluminium), parmi les plus grandes du monde, ainsi que de l'or et des diamants. Elle est le premier pays francophone à avoir refusé d'entrer dans la Communauté française en 1958, sous Sékou Touré. Elle n'en reste pas moins politiquement instable, avec plusieurs coups d'État à son histoire." },
  "gw": { population: "2 millions", languages: "Portugais, Créole guinéen", currency: "Franc CFA (XOF)", summary: "Parmi les pays les plus pauvres du monde, la Guinée-Bissau a connu de nombreux coups d'État depuis son indépendance du Portugal en 1974. Elle est tristement connue comme une plaque tournante majeure du trafic de cocaïne entre l'Amérique latine et l'Europe, transitant par son archipel des Bijagós." },
  "ke": { population: "56 millions", languages: "Swahili, Anglais", currency: "Shilling kényan (KES)", summary: "Berceau des marathoniens les plus titrés du monde, le Kenya domine les podiums olympiques de fond depuis des décennies. Le parc national Maasaï Mara est le théâtre de la plus grande migration animale de la planète. Indépendant depuis 1963, il est le principal hub économique et technologique d'Afrique de l'Est (« Silicon Savannah »)." },
  "ls": { population: "2,2 millions", languages: "Sesotho, Anglais", currency: "Loti (LSL)", summary: "Royaume montagneux entièrement enclavé dans l'Afrique du Sud, le Lesotho est surnommé le « Royaume dans le ciel » car son point le plus bas (1 400 m) est le plus élevé de tous les pays du monde. Il est aussi l'un des pays les plus touchés par le VIH/SIDA avec un taux d'environ 25 % parmi les adultes." },
  "lr": { population: "5,5 millions", languages: "Anglais", currency: "Dollar libérien (LRD)", summary: "Fondé en 1847 par des esclaves africains affranchis de retour des États-Unis, le Libéria est la plus ancienne république africaine. Il a connu deux guerres civiles dévastatrices (1989–2003), marquées par l'utilisation massive d'enfants soldats. Ellen Johnson Sirleaf, élue présidente en 2005, fut la première femme chef d'État d'Afrique." },
  "ly": { population: "7 millions", languages: "Arabe", currency: "Dinar libyen (LYD)", summary: "La Libye détient les plus grandes réserves de pétrole d'Afrique. Elle a été gouvernée pendant 42 ans par Mouammar Kadhafi (1969–2011), dont le régime excentrique et imprévisible finançait de nombreux mouvements révolutionnaires dans le monde. La révolution de 2011, soutenue par l'OTAN, a entraîné la mort de Kadhafi et plongé le pays dans une guerre civile continue." },
  "mg": { population: "29 millions", languages: "Malgache, Français", currency: "Ariary (MGA)", summary: "Isolée du reste du monde depuis 80 millions d'années, Madagascar abrite une faune et flore uniques au monde : 90 % de ses espèces sont endémiques, dont les lémuriens et les fossas. L'île a été peuplée il y a environ 2 000 ans par des navigateurs austronésiens venus d'Indonésie, constituant l'une des migrations humaines les plus remarquables." },
  "mw": { population: "20 millions", languages: "Chichewa, Anglais", currency: "Kwacha malawien (MWK)", summary: "Surnommé le « Cœur chaud de l'Afrique » pour l'hospitalité légendaire de ses habitants. Le lac Malawi (Nyasa) est l'un des plus grands au monde et abrite plus de 500 espèces de cichlidés, la plus grande diversité de poissons d'eau douce au monde. C'est l'un des pays les plus pauvres du continent malgré ses ressources agricoles." },
  "ml": { population: "23 millions", languages: "Français, Bambara", currency: "Franc CFA (XOF)", summary: "Berceau de grands empires médiévaux successifs — le Ghana, le Mali et le Songhaï — qui dominèrent le commerce transsaharien de l'or et du sel. Tombouctou fut au XVe siècle un foyer intellectuel islamique rayonnant, avec ses universités et ses bibliothèques de manuscrits. Depuis 2012, le Mali est déstabilisé par une rébellion touarègue et une insurrection jihadiste." },
  "mr": { population: "4,7 millions", languages: "Arabe, Pular, Soninké, Wolof", currency: "Ouguiya (MRO)", summary: "Pont géographique et culturel entre l'Afrique arabe et l'Afrique subsaharienne, la Mauritanie reste l'un des derniers pays où l'esclavage, officiellement aboli en 1981, perdure dans les pratiques sociales. Son territoire est recouvert à 90 % par le Sahara, mais ses côtes atlantiques abritent l'une des zones de pêche les plus riches du monde." },
  "mu": { population: "1,3 million", languages: "Créole mauricien, Anglais, Français", currency: "Roupie mauricienne (MUR)", summary: "Île sans population autochtone, Maurice a été colonisée successivement par les Hollandais, les Français puis les Britanniques. Elle est célèbre pour avoir hébergé le dodo, l'oiseau emblème de l'extinction, disparu à la fin du XVIIe siècle. Aujourd'hui, elle jouit d'une des économies les plus diversifiées et les plus prospères d'Afrique." },
  "ma": { population: "37 millions", languages: "Arabe, Amazigh (berbère)", currency: "Dirham (MAD)", summary: "Carrefour millénaire entre l'Europe, l'Afrique et le monde arabe, le Maroc abrite quatre anciennes capitales impériales — Marrakech, Fès, Meknès et Rabat. Seul pays africain membre du G20 et candidat à l'adhésion à l'UE, il est aujourd'hui la principale puissance économique du Maghreb. La médina de Fès est considérée comme la plus ancienne université du monde encore en activité (859 ap. J.-C.)." },
  "mz": { population: "33 millions", languages: "Portugais", currency: "Metical (MZN)", summary: "Colonisé par le Portugal jusqu'en 1975, le Mozambique est immédiatement plongé dans une guerre civile de 16 ans. Il possède une longue côte sur l'océan Indien qui en fit un carrefour commercial important depuis l'Antiquité. La découverte de vastes gisements de gaz naturel au large du Cabo Delgado dans les années 2010 attise aujourd'hui conflits et convoitises." },
  "na": { population: "2,6 millions", languages: "Anglais, Afrikaans, Oshivambo", currency: "Dollar namibien (NAD)", summary: "Le désert du Namib, qui lui donne son nom, est l'un des plus anciens déserts du monde (55 millions d'années) et abrite les dunes les plus hautes de la planète à Sossusvlei. Ancienne colonie allemande (Südwestafrika), la Namibie a été administrée par l'Afrique du Sud sous apartheid avant d'accéder à l'indépendance en 1990." },
  "ne": { population: "25 millions", languages: "Français, Haoussa, Zarma", currency: "Franc CFA (XOF)", summary: "Plus grand pays d'Afrique de l'Ouest, le Niger est couvert à 80 % par le Sahara. Paradoxe : premier producteur d'uranium d'Afrique, il figure en dernière position de l'Indice de Développement Humain des Nations Unies. Il est régulièrement touché par des sécheresses et fait face à une insurrection jihadiste aux frontières du Mali et du Nigeria." },
  "ng": { population: "220 millions", languages: "Anglais, Haoussa, Yoruba, Igbo", currency: "Naira (NGN)", summary: "Pays le plus peuplé d'Afrique et première économie du continent, le Nigeria est une puissance culturelle et économique majeure. Nollywood, son industrie cinématographique, est la deuxième au monde par le volume de production, devant Hollywood. Malgré ses immenses ressources pétrolières, des inégalités criantes et la corruption persistent." },
  "rw": { population: "14 millions", languages: "Kinyarwanda, Français, Anglais", currency: "Franc rwandais (RWF)", summary: "En 1994, le Rwanda a subi l'un des génocides les plus rapides de l'histoire : environ 800 000 Tutsis et Hutus modérés tués en 100 jours. Depuis, le pays a connu une reconstruction remarquable sous Paul Kagame, devenant l'un des pays les plus propres et les mieux gouvernés d'Afrique, et pionniers de la parité femmes-hommes au Parlement." },
  "st": { population: "220 000", languages: "Portugais, Créole forro", currency: "Dobra (STN)", summary: "Petit archipel du golfe de Guinée, ancienne colonie portugaise indépendante depuis 1975, São Tomé-et-Príncipe fut au XIXe siècle le premier producteur mondial de cacao. C'est aujourd'hui une démocratie stable et une destination écotouristique émergente. Des réserves de pétrole ont été découvertes dans ses eaux territoriales, promesse d'un avenir économique à redéfinir." },
  "sn": { population: "17 millions", languages: "Français, Wolof", currency: "Franc CFA (XOF)", summary: "L'un des pays les plus stables d'Afrique de l'Ouest, le Sénégal n'a jamais connu de coup d'État depuis son indépendance en 1960. Dakar, ancienne capitale de l'AOF (Afrique-Occidentale française), reste un carrefour culturel et économique régional majeur. La Teranga (hospitalité) est un pilier de l'identité nationale sénégalaise." },
  "sl": { population: "8,5 millions", languages: "Anglais, Krio, Temné, Mende", currency: "Leone (SLL)", summary: "Fondée en 1787 comme colonie d'accueil pour les esclaves affranchis de retour d'Angleterre, Freetown est l'une des plus vieilles villes-refuge du continent. La Sierra Leone a subi une guerre civile brutale (1991–2002) tristement connue pour les mutilations des civils et l'utilisation d'enfants soldats. Elle a été l'épicentre de l'épidémie d'Ebola de 2014–2016." },
  "so": { population: "18 millions", languages: "Somali, Arabe", currency: "Shilling somalien (SOS)", summary: "État de la Corne de l'Afrique qui s'effondre en 1991 après la chute du dictateur Siad Barré, plongeant le pays dans une guerre civile sans fin. La piraterie maritime somalienne atteint son apogée entre 2008 et 2012, menaçant l'une des routes commerciales les plus fréquentées du monde. La région du Somaliland a déclaré son indépendance mais n'est reconnue par aucun État." },
  "za": { population: "62 millions", languages: "Zoulou, Xhosa, Afrikaans, Anglais (11 langues officielles)", currency: "Rand (ZAR)", summary: "L'Afrique du Sud a vécu sous le régime de ségrégation raciale de l'apartheid jusqu'en 1994. Nelson Mandela, emprisonné 27 ans à Robben Island, est devenu le premier président noir élu et un symbole mondial de paix et de réconciliation. C'est la première économie industrialisée du continent, et le seul pays à avoir développé puis renoncé volontairement à l'arme nucléaire." },
  "ss": { population: "11 millions", languages: "Anglais, Dinka, Nuer", currency: "Livre sud-soudanaise (SSP)", summary: "Né en 2011 après un référendum d'autodétermination suivant deux guerres civiles avec le Soudan, le Soudan du Sud est le plus jeune pays reconnu du monde. Il est presque immédiatement retombé dans une guerre civile fratricide (2013–2020), l'une des crises humanitaires les plus graves d'Afrique, malgré ses importantes réserves de pétrole." },
  "sd": { population: "46 millions", languages: "Arabe, Anglais", currency: "Livre soudanaise (SDG)", summary: "Berceau de l'antique Nubie et de plusieurs royaumes florissants (Méroé et ses pyramides, Kush), le Soudan est le pays qui compte le plus de pyramides au monde — plus même que l'Égypte. Scindé en deux en 2011 avec l'indépendance du Soudan du Sud, il traverse depuis 2023 une guerre civile catastrophique entre les forces armées soudanaises et les paramilitaires RSF." },
  "tz": { population: "65 millions", languages: "Swahili, Anglais", currency: "Shilling tanzanien (TZS)", summary: "La Tanzanie abrite le Kilimandjaro (5 895 m), la plus haute montagne d'Afrique, et le Serengeti, scène de la grande migration annuelle d'un million et demi de gnous. L'île de Zanzibar fut un important sultanat arabe et un grand centre du commerce des épices et des esclaves. Les gorges d'Olduvai ont livré certains des plus anciens fossiles humains connus." },
  "tg": { population: "9 millions", languages: "Français, Éwé, Kabiyé", currency: "Franc CFA (XOF)", summary: "L'un des pays les plus étroits du monde (56 km de large en certains points), le Togo est indépendant depuis 1960. Il est gouverné par la famille Gnassingbé depuis 1967, ce qui en fait l'une des plus longues dynasties politiques du monde. Son port de Lomé est l'un des plus importants de l'Afrique de l'Ouest." },
  "tn": { population: "12 millions", languages: "Arabe, Berbère", currency: "Dinar tunisien (TND)", summary: "Berceau de la puissante civilisation carthaginoise (IXe–IIe siècles av. J.-C.), rivale de Rome, la Tunisie est au carrefour de la Méditerranée. En 2010–2011, elle est le premier pays à renverser son dictateur lors du Printemps arabe — la révolution du Jasmin — et à réussir, au moins partiellement, une transition démocratique." },
  "ug": { population: "48 millions", languages: "Anglais, Swahili, Luganda", currency: "Shilling ougandais (UGX)", summary: "L'Ouganda abrite la source du Nil Blanc au lac Victoria, le plus grand lac tropical du monde. Il a vécu sous la dictature sanglante d'Idi Amin Dada (1971–1979), dont le régime provoqua la mort de 100 000 à 500 000 personnes. Aujourd'hui, le pays a l'une des populations les plus jeunes du monde, avec un âge médian d'environ 16 ans." },
  "zm": { population: "20 millions", languages: "Anglais, Bemba, Nyanja", currency: "Kwacha (ZMW)", summary: "La Zambie abrite les chutes Victoria (Mosi-oa-Tunya), parmi les plus spectaculaires du monde, classées au patrimoine de l'UNESCO. Elle tire son nom du fleuve Zambèze et fut la colonie britannique de Rhodésie du Nord. Indépendante depuis 1964, elle est l'un des principaux producteurs mondiaux de cuivre et de cobalt." },
  "zw": { population: "16 millions", languages: "Shona, Ndebele, Anglais (16 langues officielles)", currency: "Dollar zimbabwéen (ZWL)", summary: "Le Zimbabwe tire son nom des ruines du Grand Zimbabwe (XIe–XVe siècle), témoignage d'un empire médiéval africain prospère. Gouverné par Robert Mugabe depuis l'indépendance (1980), le pays connaît une hyperinflation record en 2008 (taux annuel de 89 septillions de pourcent), effaçant l'épargne de tout un peuple. Mugabe est destitué par un coup d'État en 2017." },

  // ===== AMÉRIQUES =====
  "ag": { population: "100 000", languages: "Anglais", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Ancienne colonie britannique de production sucrière reposant sur l'esclavage, Antigua-et-Barbuda accède à l'indépendance en 1981. L'archipel est aujourd'hui fortement dépendant du tourisme et des services financiers. La quasi-totalité de l'île de Barbuda a été détruite par l'ouragan Irma en 2017, forçant l'évacuation complète de sa population." },
  "ar": { population: "45 millions", languages: "Espagnol", currency: "Peso argentin (ARS)", summary: "Deuxième plus grand pays d'Amérique du Sud, l'Argentine est le berceau du tango et d'une culture footballistique unique (Maradona, Messi). Elle a connu une dictature militaire (1976–1983) responsable de la disparition de 30 000 personnes. La crise économique de 2001, l'une des plus graves de l'histoire, a vu cinq présidents se succéder en deux semaines." },
  "bs": { population: "400 000", languages: "Anglais", currency: "Dollar des Bahamas (BSD)", summary: "Archipel de quelque 700 îles dans les Caraïbes, les Bahamas ont une importance historique majeure : Christophe Colomb y effectua son premier débarquement en Amérique le 12 octobre 1492, sur l'île de Guanahani (San Salvador). Indépendant depuis 1973, le pays vit principalement du tourisme et de la finance offshore." },
  "bb": { population: "290 000", languages: "Anglais, Créole bajan", currency: "Dollar de Barbade (BBD)", summary: "Ancienne colonie britannique dont la production sucrière esclavagiste fit la fortune de l'Angleterre au XVIIe siècle. La Barbade est devenue une République en 2021, retirant le monarque britannique comme chef d'État. Elle est l'île natale de la chanteuse Rihanna, nommée ambassadrice nationale en 2021." },
  "bz": { population: "430 000", languages: "Anglais, Créole bélizien, Espagnol", currency: "Dollar bélizien (BZD)", summary: "Seul pays d'Amérique centrale dont la langue officielle est l'anglais, le Belize abrite le deuxième plus grand récif corallien du monde (barrière de corail mésoaméricaine) ainsi que de nombreux sites archéologiques mayas, dont Caracol. Il est indépendant depuis 1981 et constitue la plus jeune nation d'Amérique centrale." },
  "bo": { population: "12 millions", languages: "Espagnol, Quechua, Aymara (36 langues officielles)", currency: "Boliviano (BOB)", summary: "La Bolivie a perdu son accès à la mer au Chili lors de la Guerre du Pacifique (1879–1884) — un traumatisme national encore vif aujourd'hui. La Paz, siège du gouvernement, est la plus haute capitale administrative du monde (3 600 m). Evo Morales, premier président indigène du pays (2006–2019), a profondément transformé sa constitution et son identité nationale." },
  "br": { population: "215 millions", languages: "Portugais", currency: "Real brésilien (BRL)", summary: "Plus grand pays d'Amérique latine et cinquième du monde, le Brésil est une puissance culturelle mondiale — samba, carnaval, football, Pelé. La forêt amazonienne, qui couvre 60 % de son territoire, est le plus grand écosystème tropical de la planète, abritant 10 % des espèces vivantes connues. Brasília, sa capitale futuriste, a été construite de toutes pièces en trois ans (1957–1960)." },
  "ca": { population: "39 millions", languages: "Anglais, Français", currency: "Dollar canadien (CAD)", summary: "Deuxième plus grand pays du monde en superficie, le Canada est reconnu pour son multiculturalisme, son système de santé universel et sa stabilité démocratique. Pays fondateur de l'ONU et membre du G7, il est peuplé depuis des millénaires par des Premières Nations dont la réconciliation est un enjeu central contemporain. La région du Québec maintient une identité francophone unique en Amérique du Nord." },
  "cl": { population: "19 millions", languages: "Espagnol", currency: "Peso chilien (CLP)", summary: "Pays le plus long du monde du nord au sud (4 300 km), le Chili s'étend du désert d'Atacama (le plus aride du monde) aux glaciers de Patagonie. Il a vécu sous la dictature d'Augusto Pinochet (1973–1990), arrivé au pouvoir par un coup d'État contre le socialiste Salvador Allende. L'île de Pâques (Rapa Nui), avec ses mystérieux moaïs, appartient au Chili." },
  "co": { population: "52 millions", languages: "Espagnol", currency: "Peso colombien (COP)", summary: "Seul pays d'Amérique du Sud avec une façade sur l'Atlantique et le Pacifique, la Colombie est le berceau du réalisme magique littéraire avec Gabriel García Márquez (Prix Nobel 1982). Longtemps dévastée par le conflit avec les FARC et le narcotraffic (cartel de Medellín de Pablo Escobar), elle a signé un accord de paix historique en 2016." },
  "cr": { population: "5 millions", languages: "Espagnol", currency: "Colón (CRC)", summary: "Le Costa Rica a aboli son armée en 1948, l'une des démocraties les plus stables et pacifiques d'Amérique centrale. Pionnier de l'écotourisme, il protège 25 % de son territoire et produit plus de 99 % de son électricité à partir de sources renouvelables. Son slogan national « Pura Vida » incarne une philosophie de bien-être largement reconnue." },
  "cu": { population: "11 millions", languages: "Espagnol", currency: "Peso cubain (CUP)", summary: "La révolution castriste de 1959, menée par Fidel Castro et Ernesto Che Guevara, renverse le dictateur Batista et instaure le seul régime communiste des Amériques. La crise des missiles de 1962 y met le monde au bord d'une guerre nucléaire. Cuba possède un système de santé et d'éducation remarquables malgré l'embargo américain en vigueur depuis 1962." },
  "dm": { population: "72 000", languages: "Anglais, Créole dominicais", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Surnommée l'« île Nature » pour ses forêts tropicales luxuriantes, ses sources géothermiques et sa biodiversité exceptionnelle, la Dominique est l'une des destinations les moins touristiques et les plus authentiques des Caraïbes. Elle cherche à devenir la première nation entièrement alimentée par l'énergie géothermique." },
  "do": { population: "11 millions", languages: "Espagnol", currency: "Peso dominicain (DOP)", summary: "La République dominicaine partage l'île d'Hispaniola avec Haïti. Christophe Colomb y établit en 1496 le premier établissement européen permanent des Amériques, Santo Domingo — la ville la plus ancienne du Nouveau Monde. Aujourd'hui première destination touristique des Caraïbes, elle connaît l'une des croissances économiques les plus rapides de la région." },
  "ec": { population: "18 millions", languages: "Espagnol, Quechua", currency: "Dollar américain (USD)", summary: "L'Équateur doit son nom à la ligne de l'équateur qui traverse son territoire. Les îles Galápagos, archipel équatorien du Pacifique, ont inspiré la théorie de l'évolution par sélection naturelle de Charles Darwin en 1835. L'Équateur est le premier pays au monde à avoir inscrit les droits de la nature dans sa constitution (2008)." },
  "sv": { population: "6,5 millions", languages: "Espagnol", currency: "Dollar américain (USD)", summary: "Le pays le plus densément peuplé d'Amérique centrale a vécu une guerre civile dévastatrice (1979–1992) entre la junte militaire et le FMLN, qui fit 75 000 morts. En 2021, El Salvador est devenu le premier pays au monde à adopter le Bitcoin comme monnaie légale. Il lutte contre des gangs (Mara Salvatrucha) qui ont longtemps fait de lui l'un des pays les plus violents du monde." },
  "gd": { population: "125 000", languages: "Anglais, Créole grenadien", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Surnommée l'« île aux épices » pour sa production de muscade (deuxième producteur mondial), la Grenade est la plus méridionale des îles du Vent. Elle a été envahie par les États-Unis en 1983 après un coup d'État marxiste, dans l'une des dernières interventions militaires directes de la Guerre froide dans les Amériques." },
  "gt": { population: "18 millions", languages: "Espagnol, Langues mayas", currency: "Quetzal (GTQ)", summary: "Cœur de la brillante civilisation maya classique, le Guatemala abrite des sites archéologiques exceptionnels comme Tikal, ancienne cité de 100 000 habitants. Il a vécu la guerre civile la plus longue d'Amérique latine (1960–1996), avec 200 000 morts, majoritairement des Mayas victimes de massacres reconnus comme génocide." },
  "gl": { population: "57 000", languages: "Groenlandais (Kalaallisut), Danois", currency: "Couronne danoise (DKK)", summary: "Plus grande île du monde (2,17 millions de km²), le Groenland est un territoire autonome du Danemark habité depuis 4 500 ans par des peuples inuits. Sa calotte glaciaire contient environ 10 % des eaux douces mondiales ; sa fonte totale élèverait le niveau des mers de 7 mètres. Sa position géopolitique stratégique en fait l'objet de convoitises, notamment américaines." },
  "gy": { population: "800 000", languages: "Anglais, Créole guyanien", currency: "Dollar guyanien (GYD)", summary: "Seul pays anglophone d'Amérique du Sud, le Guyana abrite d'immenses forêts tropicales pratiquement intactes. Il est tristement connu pour la tragédie de Jonestown (1978), où 918 membres du Temple du Peuple de Jim Jones se sont suicidés collectivement, la plus grande perte civile américaine de l'histoire avant le 11 septembre." },
  "ht": { population: "12 millions", languages: "Créole haïtien, Français", currency: "Gourde (HTG)", summary: "En 1804, Haïti est devenue la première nation noire à obtenir son indépendance, suite à la seule révolte d'esclaves réussie de l'histoire. Ce succès lui valut l'isolement diplomatique et économique de la part des puissances esclavagistes. Frappée par un séisme dévastateur en 2010 (200 000 morts), elle est aujourd'hui l'un des pays les plus pauvres des Amériques." },
  "hn": { population: "10 millions", languages: "Espagnol", currency: "Lempira (HNL)", summary: "Le Honduras abrite les ruines mayas de Copán, considérées comme le Paris de la civilisation maya pour la qualité de leurs sculptures. Il a été surnommé « République bananière » — terme né ici — en raison de la domination écrasante des compagnies américaines de fruits au XXe siècle. Il souffre encore aujourd'hui d'une forte violence liée aux gangs et au trafic de drogue." },
  "jm": { population: "2,8 millions", languages: "Anglais, Patois jamaïcain", currency: "Dollar jamaïcain (JMD)", summary: "La Jamaïque est le berceau du reggae, du ska, du dancehall et de Bob Marley, dont la musique a conquis le monde entier. Elle a dominé le sprint mondial depuis les années 2000, notamment avec Usain Bolt, le sprinter le plus rapide de l'histoire. Le mouvement rastafari, né en Jamaïque dans les années 1930, a eu une influence culturelle mondiale considérable." },
  "mx": { population: "130 millions", languages: "Espagnol", currency: "Peso mexicain (MXN)", summary: "Berceau de brillantes civilisations précolombiennes — les Olmèques, les Mayas et les Aztèques dont la capitale Tenochtitlan stupéfia les conquistadors. Deuxième plus grande économie d'Amérique latine, le Mexique est lié aux États-Unis par l'accord de libre-échange NAFTA/USMCA. Le pays est la patrie de grandes icônes culturelles : Diego Rivera, Frida Kahlo, Octavio Paz." },
  "ni": { population: "7 millions", languages: "Espagnol", currency: "Córdoba (NIO)", summary: "Plus grand pays d'Amérique centrale, le Nicaragua a vécu une révolution sandiniste en 1979 qui renversa la dictature de Somoza, puis une guerre des Contras financée par les États-Unis dans les années 1980. Après une courte période démocratique, le pays est retourné à l'autoritarisme sous Daniel Ortega, président depuis 2007." },
  "pa": { population: "4,3 millions", languages: "Espagnol, Anglais", currency: "Balboa / Dollar américain (PAB/USD)", summary: "Le canal de Panama, inauguré en 1914 après la mort de 27 000 ouvriers, est l'une des réalisations d'ingénierie les plus importantes de l'histoire, reliant les océans Atlantique et Pacifique. Séparé de la Colombie en 1903 avec l'aide des États-Unis, Panama ne récupère le canal qu'en 1999. Les Îles San Blas sont le territoire des Kunas, l'un des peuples indigènes les mieux préservés des Amériques." },
  "py": { population: "7,5 millions", languages: "Espagnol, Guaraní", currency: "Guaraní (PYG)", summary: "L'un des deux pays d'Amérique du Sud sans accès à la mer, le Paraguay est le seul à détenir une proportion aussi élevée de locuteurs d'une langue indigène (le guaraní est co-officiel et parlé par 90 % de la population). Il a vécu sous la dictature d'Alfredo Stroessner pendant 35 ans (1954–1989), l'une des plus longues d'Amérique latine." },
  "pe": { population: "33 millions", languages: "Espagnol, Quechua, Aymara", currency: "Sol (PEN)", summary: "Cœur de l'empire inca au XVe siècle, le Pérou abrite le Machu Picchu, cité mystérieuse perchée à 2 430 m dans les Andes, classée au patrimoine mondial. Le fleuve Amazone prend sa source dans les Andes péruviennes. Lima est depuis le XVIe siècle la capitale économique et politique de toute l'Amérique du Sud espagnole." },
  "kn": { population: "55 000", languages: "Anglais", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Saint-Kitts-et-Nevis est la plus petite nation des Amériques par superficie et population. L'île de Saint-Kitts fut le premier territoire colonisé par les Européens dans les Caraïbes (1623), servant de base de départ pour la colonisation de la région. La forteresse de Brimstone Hill, construite par des esclaves, est classée au patrimoine de l'UNESCO." },
  "lc": { population: "185 000", languages: "Anglais, Créole saint-lucien", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Sainte-Lucie a changé 14 fois de mains entre la France et la Grande-Bretagne avant 1814, laissant une culture profondément créole malgré la langue officielle anglaise. Elle détient le ratio de Prix Nobel par habitant le plus élevé du monde (deux lauréats : Derek Walcott en littérature et Sir Arthur Lewis en économie). Les pitons volcaniques de Gros Piton et Petit Piton sont classés au patrimoine de l'UNESCO." },
  "vc": { population: "110 000", languages: "Anglais, Créole vincentin", currency: "Dollar des Caraïbes orientales (XCD)", summary: "Archipel de 32 îles dont 9 habitées, Saint-Vincent-et-les-Grenadines est réputé pour ses eaux cristallines utilisées comme décor dans les films Pirates des Caraïbes. La Soufrière, volcan actif, a connu une éruption majeure en 2021, contraignant à l'évacuation d'un tiers de la population de l'île principale." },
  "sr": { population: "620 000", languages: "Néerlandais, Sranan Tongo", currency: "Dollar surinamais (SRD)", summary: "Seul pays néerlandophone d'Amérique du Sud, le Suriname est aussi le plus petit pays du continent. Il abrite l'une des plus grandes forêts tropicales préservées du monde, couvrant 90 % de son territoire. Sa population est l'une des plus multiethniques au monde, mélange d'Africains, d'Hindous, de Javanais, d'Amérindiens et d'Européens." },
  "tt": { population: "1,4 million", languages: "Anglais", currency: "Dollar de Trinité-et-Tobago (TTD)", summary: "Trinité-et-Tobago est le berceau du steelpan (steel drum), le seul instrument de musique acoustique inventé au XXe siècle, et du calypso. Son économie, l'une des plus développées des Caraïbes, repose sur le pétrole et le gaz naturel. Le Carnaval de Trinidad est l'un des plus célèbres et flamboyants du monde." },
  "us": { population: "335 millions", languages: "Anglais (langue de facto)", currency: "Dollar américain (USD)", summary: "Fondés en 1776 après la révolution contre la couronne britannique, les États-Unis sont devenus au XXe siècle la première puissance mondiale — économique, militaire et culturelle. Du cinéma de Hollywood à la conquête de la Lune (1969), de la Silicon Valley à Wall Street, ils ont façonné la modernité mondiale. L'élection de Barack Obama en 2008 comme premier président afro-américain fut un moment historique." },
  "uy": { population: "3,5 millions", languages: "Espagnol", currency: "Peso uruguayen (UYU)", summary: "L'Uruguay est régulièrement considéré comme la démocratie la plus solide et le pays le moins corrompu d'Amérique latine. Il fut le premier pays au monde à légaliser le cannabis récréatif (2013) et le mariage homosexuel (2013) en Amérique latine. Pays de grands élevages, il est l'un des plus grands exportateurs de bœuf au monde." },
  "ve": { population: "29 millions", languages: "Espagnol", currency: "Bolívar (VES)", summary: "Le Venezuela détient les plus grandes réserves de pétrole prouvées au monde, devant l'Arabie saoudite. Malgré cette richesse, il connaît depuis 2013 une crise politique, économique et humanitaire sans précédent, provoquant l'exode de plus de 7 millions de personnes — l'une des plus grandes crises migratoires de l'histoire des Amériques. Il est la patrie du Libertador Simón Bolívar." },

  // ===== ASIE =====
  "af": { population: "42 millions", languages: "Pachto, Dari (persan)", currency: "Afghani (AFN)", summary: "Carrefour des civilisations depuis l'Antiquité, l'Afghanistan a été traversé par Alexandre le Grand, les Mongols et les Moghols. Il a vécu 40 ans de guerre : invasion soviétique (1979–1989), guerre civile, premier régime taliban (1996–2001), puis occupation américaine et de l'OTAN suite aux attentats du 11 septembre 2001. Les talibans reprennent le pouvoir en 2021 au départ des troupes américaines." },
  "am": { population: "3 millions", languages: "Arménien", currency: "Dram (AMD)", summary: "L'Arménie est l'une des premières nations à avoir adopté le christianisme comme religion d'État en 301 ap. J.-C. Elle a subi le premier génocide officiellement reconnu du XXe siècle, perpétré par l'Empire ottoman en 1915, avec 1,5 million de victimes. Son territoire est depuis 1988 en conflit avec l'Azerbaïdjan pour le Haut-Karabagh." },
  "az": { population: "10 millions", languages: "Azéri (azerbaïdjanais)", currency: "Manat (AZN)", summary: "Bakou fut le site du premier pétrole industriel au monde à la fin du XIXe siècle, faisant de l'Azerbaïdjan une richesse convoitée. Indépendant de l'URSS depuis 1991, il est en conflit avec l'Arménie pour le Haut-Karabagh qu'il reconquiert militairement en 2020 et 2023. Bakou est surnommée la « ville des vents » et abrite une vieille ville classée au patrimoine mondial." },
  "bh": { population: "1,5 million", languages: "Arabe", currency: "Dinar bahreïni (BHD)", summary: "Petit archipel du Golfe Persique, Bahreïn est le premier pays arabe à avoir découvert du pétrole en 1932. Il accueille la Ve flotte américaine et fut longtemps le centre financier du Moyen-Orient. En 2011, les protestations du Printemps arabe y sont réprimées avec l'aide militaire de l'Arabie saoudite et des Émirats arabes unis." },
  "bd": { population: "170 millions", languages: "Bengali", currency: "Taka (BDT)", summary: "L'un des pays les plus densément peuplés du monde, le Bangladesh est né en 1971 après une guerre de libération contre le Pakistan (Bangladesh oriental), lors de laquelle l'armée pakistanaise a commis un génocide estimé entre 300 000 et 3 millions de morts. Vulnérable aux cyclones et aux inondations, il est pionnier dans la lutte contre le changement climatique et dans le microcrédit (Grameen Bank de Muhammad Yunus)." },
  "bt": { population: "780 000", languages: "Dzongkha", currency: "Ngultrum (BTN)", summary: "Seul pays au monde à mesurer officiellement le Bonheur National Brut (BNB) comme indicateur de développement, le Bhoutan est resté volontairement isolé jusqu'aux années 1970. La télévision et Internet n'y ont été autorisés qu'en 1999. Pays bouddhiste himalayen, il a longtemps interdit le tourisme de masse pour préserver sa culture et son environnement." },
  "bn": { population: "450 000", languages: "Malais", currency: "Dollar de Brunéi (BND)", summary: "Sultanat pétrolier parmi les plus riches du monde, Brunéi offre à ses citoyens l'éducation et la santé entièrement gratuites. Gouverné depuis 1967 par le Sultan Hassanal Bolkiah, l'un des monarques au pouvoir depuis le plus longtemps et l'un des hommes les plus riches du monde. En 2019, il a suscité une vague d'indignation en instaurant la charia pénale." },
  "kh": { population: "17 millions", languages: "Khmer", currency: "Riel (KHR)", summary: "Berceau de l'empire khmer (IXe–XVe siècle), l'un des empires les plus puissants d'Asie du Sud-Est, dont le temple d'Angkor Vat est le plus grand édifice religieux du monde. Le Cambodge a subi le génocide des Khmers rouges de Pol Pot (1975–1979), qui a tué entre 1,5 et 2 millions de personnes — environ un quart de la population. Le pays se reconstruit lentement depuis les accords de Paris de 1991." },
  "cn": { population: "1,4 milliard", languages: "Mandarin (putonghua)", currency: "Yuan / Renminbi (CNY)", summary: "La Chine est la plus grande civilisation continue du monde avec plus de 5 000 ans d'histoire — papier, imprimerie, boussole, poudre à canon. Après des décennies de pauvreté sous Mao Zedong, les réformes économiques de Deng Xiaoping (1978) ont propulsé la Chine au rang de deuxième puissance économique mondiale. La Grande Muraille (plusieurs millénaires de construction) et la Route de la Soie symbolisent son influence historique." },
  "ge": { population: "3,7 millions", languages: "Géorgien", currency: "Lari (GEL)", summary: "La Géorgie est considérée comme le berceau de la viticulture, avec des traces de production de vin vieilles de 8 000 ans. Ancienne république soviétique indépendante depuis 1991, elle a vécu la guerre avec la Russie en 2008 (qui a reconnu l'Ossétie du Sud et l'Abkhazie comme indépendantes) et une révolution de velours (révolution des Roses) en 2003. Ses aspirations européennes se heurtent à l'influence russe." },
  "in": { population: "1,4 milliard", languages: "Hindi, Anglais (22 langues officielles)", currency: "Roupie indienne (INR)", summary: "Plus grande démocratie du monde, l'Inde est le berceau de civilisations antiques (culture de l'Indus) et de grandes religions (hindouisme, bouddhisme, jaïnisme). Elle obtient son indépendance du Royaume-Uni en 1947 grâce au mouvement non-violent de Gandhi. Depuis les années 1990, son économie est l'une des plus dynamiques du monde, et elle est en 2023 le pays le plus peuplé du globe." },
  "id": { population: "275 millions", languages: "Bahasa Indonesia", currency: "Roupie (IDR)", summary: "Plus grand archipel du monde avec 17 000 îles et quatrième nation la plus peuplée, l'Indonésie abrite la plus grande communauté musulmane du monde. Elle a vécu sous la dictature de Suharto (1967–1998), puis a réussi une transition démocratique remarquable. Le temple de Borobudur à Java est le plus grand monument bouddhiste au monde." },
  "ir": { population: "88 millions", languages: "Persan (farsi)", currency: "Rial (IRR)", summary: "Berceau de la civilisation perse et de l'empire achéménide (Cyrus le Grand, 550 av. J.-C.), l'Iran est l'une des plus vieilles nations du monde. La révolution islamique de 1979 menée par l'ayatollah Khomeini renverse le Shah et instaure une République islamique. Depuis lors, l'Iran est en confrontation avec les États-Unis et Israël, développant un programme nucléaire controversé." },
  "iq": { population: "43 millions", languages: "Arabe, Kurde", currency: "Dinar irakien (IQD)", summary: "La Mésopotamie, entre le Tigre et l'Euphrate, est le berceau des premières civilisations humaines — Sumer, Akkad, Babylone — et de l'écriture cunéiforme. L'Irak a subi la guerre contre l'Iran (1980–1988), l'invasion du Koweït (1990), la Guerre du Golfe (1991) et l'invasion américaine (2003) qui déstabilise toute la région et ouvre la voie à l'émergence de Daesh." },
  "il": { population: "9,3 millions", languages: "Hébreu, Arabe", currency: "Shekel nouveau (ILS)", summary: "Fondé en 1948 sur la terre biblique, Israël est au cœur du conflit israélo-palestinien depuis sa création. Surnommée « Start-Up Nation », Israël est l'un des pays les plus innovants au monde en matière de technologies (cybersécurité, agriculture, médecine). Jérusalem, ville sainte des trois grandes religions monothéistes, en est la capitale revendiquée mais non reconnue par la majorité des États." },
  "jp": { population: "125 millions", languages: "Japonais", currency: "Yen (JPY)", summary: "Le Japon est le seul pays à avoir subi des bombardements atomiques (Hiroshima et Nagasaki, août 1945). Après une reconstruction économique spectaculaire, il devient la deuxième puis la troisième économie mondiale. Sa culture unique — samouraïs, geishas, arts martiaux, manga, anime, cuisine kaiseki — a exercé une influence culturelle planétaire profonde." },
  "jo": { population: "10 millions", languages: "Arabe", currency: "Dinar jordanien (JOD)", summary: "La Jordanie abrite Pétra, la cité nabatéenne taillée dans la roche rose au IVe siècle av. J.-C., classée parmi les sept merveilles du monde moderne. Monarchie constitutionnelle hachémite dans une région très instable, elle a accueilli des millions de réfugiés palestiniens, irakiens et syriens. La mer Morte, à 430 m sous le niveau de la mer, est le point le plus bas des terres émergées." },
  "kz": { population: "20 millions", languages: "Kazakh, Russe", currency: "Tenge (KZT)", summary: "Neuvième plus grand pays du monde et le plus grand pays enclavé de la planète, le Kazakhstan est l'héritier des grandes steppes nomades d'Asie centrale. Il abrite le cosmodrome de Baïkonour, d'où furent lancés le premier satellite artificiel Spoutnik (1957) et le premier cosmonaute Gagarine (1961). Il détient d'importantes réserves de pétrole, de gaz et d'uranium." },
  "kw": { population: "4,4 millions", languages: "Arabe", currency: "Dinar koweïtien (KWD)", summary: "Petit émirat pétrolier du Golfe Persique parmi les plus riches du monde par habitant, le Koweït a été envahi et annexé par l'Irak en août 1990. La coalition internationale menée par les États-Unis le libère lors de la Guerre du Golfe (1991) en 42 jours. Ses gisements pétroliers représentent environ 6 % des réserves mondiales prouvées." },
  "kg": { population: "7 millions", languages: "Kirghiz, Russe", currency: "Som (KGS)", summary: "Pays montagneux d'Asie centrale dont 94 % du territoire dépasse 1 000 m d'altitude, le Kirghizstan est la patrie de nomades cavaliers dont le mode de vie ancestral se perpétue dans les yourtes. L'épopée de Manas, récitée oralement, est l'un des plus longs textes épiques du monde (20 fois l'Iliade). Il a connu deux révolutions populaires en 2005 et 2010." },
  "la": { population: "7,4 millions", languages: "Laotien", currency: "Kip (LAK)", summary: "Le Laos est le pays le plus bombardé de l'histoire par habitant : les États-Unis y ont largué plus de 2 millions de tonnes de bombes entre 1964 et 1973 (guerre du Vietnam), dont 30 % n'ont pas explosé et continuent de tuer. Seul pays enclavé d'Asie du Sud-Est, il est gouverné par le Parti révolutionnaire populaire lao depuis 1975. Le Mékong, veine vitale, traverse tout son territoire." },
  "lb": { population: "5,5 millions", languages: "Arabe, Français, Anglais", currency: "Livre libanaise (LBP)", summary: "Le Liban est le berceau de la civilisation phénicienne et de l'alphabet, l'une des plus grandes inventions de l'humanité. Surnommé la « Suisse du Moyen-Orient » pour sa prospérité passée, il a vécu une guerre civile de 15 ans (1975–1990). L'explosion du port de Beyrouth en août 2020, l'une des plus puissantes de l'histoire non nucléaire, a ravagé la capitale déjà en pleine crise économique." },
  "my": { population: "33 millions", languages: "Malais, Anglais, Mandarin, Tamoul", currency: "Ringgit (MYR)", summary: "La Malaisie est l'une des économies à la croissance la plus rapide d'Asie du Sud-Est depuis son indépendance en 1957. Elle abrite les tours Petronas à Kuala Lumpur, qui furent les plus hautes du monde de 1998 à 2004. Son histoire est marquée par une diversité ethnique remarquable : Malais, Chinois, Indiens — une mosaïque culturelle unique." },
  "mv": { population: "530 000", languages: "Maldivien (Dhivehi)", currency: "Rufiyaa (MVR)", summary: "Le pays le plus plat du monde avec une altitude maximale de 2,4 mètres, les Maldives sont menacées d'engloutissement par la montée des eaux liée au changement climatique. En 2009, son gouvernement a tenu un conseil des ministres sous l'eau pour alerter l'opinion mondiale. Archipel de 1 200 îles coralliennes, c'est aujourd'hui l'une des destinations touristiques les plus prisées du monde." },
  "mn": { population: "3,4 millions", languages: "Mongol", currency: "Tögrög (MNT)", summary: "La Mongolie est le berceau de Gengis Khan et du plus grand empire terrestre continu de l'histoire au XIIIe siècle, s'étendant de la mer du Japon à l'Europe centrale. C'est le pays le plus peu dense du monde (2 habitants/km²), avec la plus grande proportion de nomades. Oulan-Bator abrite une des capitales les plus froides et polluées du monde en hiver." },
  "mm": { population: "54 millions", languages: "Birman", currency: "Kyat (MMK)", summary: "La Birmanie (Myanmar) est le berceau de l'empire de Pagan (IXe–XIIIe siècle) et de la culture bouddhiste Theravāda. Gouvernée par des juntes militaires pendant la majeure partie de son histoire post-indépendance (1948), Aung San Suu Kyi y a été emprisonnée ou assignée à résidence pendant 15 ans avant d'être libérée en 2010. Un nouveau coup d'État militaire en 2021 plonge le pays dans une guerre civile." },
  "np": { population: "30 millions", languages: "Népalais", currency: "Roupie népalaise (NPR)", summary: "Le Népal abrite 8 des 10 plus hautes montagnes du monde, dont l'Everest (8 849 m), sommet du monde gravi pour la première fois en 1953 par Edmund Hillary et Tenzing Norgay. C'est le seul pays au monde avec un drapeau non rectangulaire (deux triangles superposés). Il est aussi le berceau du bouddhisme, le prince Siddhartha Gautama étant né à Lumbini." },
  "kp": { population: "26 millions", languages: "Coréen", currency: "Won nord-coréen (KPW)", summary: "La Corée du Nord est l'État le plus isolé et l'une des dictatures les plus totalitaires du monde, dirigée par la dynasty Kim depuis 1948 (Kim Il-sung, Kim Jong-il, Kim Jong-un). Elle a développé des armes nucléaires et des missiles balistiques intercontinentaux en dépit des sanctions internationales. Ses citoyens vivent sous un régime de surveillance totale et de culte de la personnalité sans équivalent." },
  "om": { population: "4,5 millions", languages: "Arabe", currency: "Rial omanais (OMR)", summary: "L'Oman est un sultanat au riche héritage maritime : ses navigateurs arabes sillonnaient l'océan Indien bien avant les Européens, commerçant jusqu'en Chine et en Afrique orientale. Le Sultan Qaboos (1970–2020) a modernisé le pays tout en maintenant une politique étrangère indépendante et de médiation (notamment entre les États-Unis et l'Iran). L'Oman est l'un des pays les plus stables et ouverts de la péninsule arabique." },
  "pk": { population: "231 millions", languages: "Ourdou, Anglais (et de nombreuses autres)", currency: "Roupie pakistanaise (PKR)", summary: "Fondé en 1947 lors de la partition traumatique des Indes, le Pakistan est le cinquième pays le plus peuplé du monde. Il est devenu puissance nucléaire en 1998 (en réponse aux essais indiens), ce qui en fait une des tensions les plus dangereuses au monde avec l'Inde voisine. Il a également abrité Oussama Ben Laden, tué par les forces américaines à Abbottabad en 2011." },
  "ps": { population: "5,3 millions", languages: "Arabe", currency: "Shekel / Dinar (ILS/JOD)", summary: "Le territoire palestinien, divisé entre la Cisjordanie et la bande de Gaza, est au cœur d'un conflit avec Israël depuis 1948 (Nakba). L'OLP reconnaît Israël en 1993 lors des accords d'Oslo, mais un État palestinien indépendant n'a jamais été créé. Gaza, sous blocus depuis 2007 et sous contrôle du Hamas, est l'un des territoires les plus densément peuplés et les plus dévastés du monde." },
  "ph": { population: "115 millions", languages: "Filipino (tagalog), Anglais", currency: "Peso philippin (PHP)", summary: "Archipel de 7 641 îles, les Philippines ont été colonisées par l'Espagne pendant 333 ans puis par les États-Unis pendant 50 ans. Elles ont connu la première révolution populaire moderne sans violence (EDSA, 1986) qui a renversé la dictature de Ferdinand Marcos. Le pays est l'un des plus exposés au monde aux typhons, séismes et éruptions volcaniques." },
  "qa": { population: "2,8 millions", languages: "Arabe", currency: "Riyal qatari (QAR)", summary: "Le Qatar possède l'un des PIB par habitant les plus élevés du monde grâce à ses immenses réserves de gaz naturel (troisièmes au monde). Il a accueilli la Coupe du Monde de football en 2022, première organisée dans un pays arabe, dans des stades climatisés construits par une main-d'œuvre migrante dans des conditions dénoncées par les défenseurs des droits humains. Il finance la chaîne de télévision Al Jazeera, influente dans le monde arabe." },
  "sa": { population: "35 millions", languages: "Arabe", currency: "Riyal saoudien (SAR)", summary: "L'Arabie saoudite est le gardien des deux lieux les plus saints de l'islam — La Mecque et Médine — et la première puissance pétrolière mondiale. Fondatrice de l'OPEP en 1960, elle a utilisé l'embargo pétrolier de 1973 pour transformer l'économie mondiale. Le prince héritier Mohammed ben Salmane (MBS) mène depuis 2016 des réformes sociales (droit de conduire pour les femmes) tout en consolidant le pouvoir." },
  "sg": { population: "5,9 millions", languages: "Anglais, Mandarin, Malais, Tamoul", currency: "Dollar singapourien (SGD)", summary: "Cité-État fondée en 1965 par Lee Kuan Yew après l'expulsion de la Malaisie, Singapour est devenue en 50 ans l'un des centres financiers, portuaires et technologiques les plus importants du monde. L'un des pays les plus riches, les moins corrompus et les mieux gouvernés de la planète, il réalise cette réussite sur un territoire de 733 km² sans ressources naturelles." },
  "kr": { population: "52 millions", languages: "Coréen", currency: "Won (KRW)", summary: "Dévastée par la guerre de Corée (1950–1953), la Corée du Sud a accompli l'un des miracles économiques les plus spectaculaires de l'histoire, passant d'un pays pauvre à une économie avancée en une génération (Samsung, LG, Hyundai). Elle est aujourd'hui à l'avant-garde de la culture populaire mondiale avec le K-pop (BTS), le K-drama et le cinéma (Parasite, Palme d'Or 2019)." },
  "lk": { population: "22 millions", languages: "Sinhala, Tamoul", currency: "Roupie srilankaise (LKR)", summary: "Ancienne Ceylan, le Sri Lanka est célèbre pour son thé (Ceylon Tea) et sa biodiversité unique. Il a vécu une guerre civile de 26 ans (1983–2009) entre les Tigres tamouls (LTTE) et le gouvernement, au cours de laquelle des dizaines de milliers de civils ont péri. En 2022, une crise économique sans précédent a provoqué la fuite du président et des manifestations massives." },
  "sy": { population: "21 millions", languages: "Arabe, Kurde", currency: "Livre syrienne (SYP)", summary: "La Syrie abrite Damas, considérée comme la plus ancienne capitale continuellement habitée du monde (environ 11 000 ans). Depuis le Printemps arabe de 2011, le pays est plongé dans une guerre civile catastrophique impliquant le régime Assad, des rebelles, des jihadistes et des puissances étrangères, faisant plus de 500 000 morts et 13 millions de déplacés." },
  "tw": { population: "23 millions", languages: "Mandarin, Taïwanais (min nan)", currency: "Dollar taïwanais (TWD)", summary: "Taïwan est gouvernée par le gouvernement nationaliste de la République de Chine depuis 1949, quand Tchang Kaï-chek s'y réfugie après la victoire de Mao sur le continent. L'île est le premier producteur mondial de semi-conducteurs avancés (TSMC), composants essentiels de tous les appareils électroniques, ce qui en fait un enjeu géopolitique central au XXIe siècle." },
  "tj": { population: "10 millions", languages: "Tadjik, Russe", currency: "Somoni (TJS)", summary: "Pays le plus pauvre d'Asie centrale, le Tadjikistan est aussi le plus montagneux, avec le Pamir surnommé le « Toit du Monde » dont le pic Ismoil Somoni culmine à 7 495 m. Il a vécu une guerre civile (1992–1997) après l'indépendance de l'URSS, faisant 50 000 à 100 000 morts. L'envoi d'argent de sa diaspora représente une grande partie de son PIB." },
  "th": { population: "72 millions", languages: "Thaï", currency: "Baht (THB)", summary: "La Thaïlande est le seul pays d'Asie du Sud-Est à n'avoir jamais été colonisé par une puissance européenne. Bouddhiste à 95 %, elle est renommée pour ses temples dorés, son palais royal à Bangkok, sa cuisine et ses plages. Le pays a connu de nombreux coups d'État militaires (19 depuis 1932), mais reste une économie dynamique et la première destination touristique de la région." },
  "tl": { population: "1,3 million", languages: "Tetum, Portugais", currency: "Dollar américain (USD)", summary: "Indépendant en 2002, Timor-Leste est l'un des pays les plus jeunes du monde. Il a subi une occupation indonésienne brutale (1975–1999) au cours de laquelle un tiers de sa population est morte de violences, famines et maladies. Le leader de la résistance José Ramos-Horta a reçu le Prix Nobel de la Paix en 1996, deux ans avant l'indépendance." },
  "tr": { population: "84 millions", languages: "Turc", currency: "Livre turque (TRY)", summary: "La Turquie est l'héritière de l'Empire ottoman qui domina le Moyen-Orient, les Balkans et l'Afrique du Nord pendant six siècles. Istanbul (ancienne Constantinople et Byzance) est la seule métropole mondiale à cheval sur deux continents (Europe et Asie). Mustapha Kemal Atatürk a fondé la République turque moderne en 1923, séparant l'État de la religion et romanisant l'alphabet." },
  "tm": { population: "6 millions", languages: "Turkmène", currency: "Manat (TMT)", summary: "L'un des États les plus fermés et autocratiques du monde, le Turkménistan est dirigé depuis l'indépendance (1991) par des présidents autoritaires aux cultes de la personnalité extravagants. Il est célèbre pour le Cratère des Portes de l'Enfer à Darvaza, un puits de gaz naturel en feu depuis 1971 que les ingénieurs soviétiques avaient allumé pensant l'éteindre en quelques semaines." },
  "ae": { population: "9,9 millions", languages: "Arabe", currency: "Dirham (AED)", summary: "Fédération de sept émirats fondée en 1971, les Émirats arabes unis ont transformé le désert en une métropole ultramoderne en quelques décennies. Dubaï abrite le Burj Khalifa (828 m), le plus haut bâtiment du monde, et ambitionne de devenir la capitale mondiale du tourisme, de la finance et de l'innovation. Abu Dhabi, l'émirat le plus riche, abrite le Louvre Abu Dhabi et investit massivement dans les arts et la culture." },
  "uz": { population: "36 millions", languages: "Ouzbek, Russe", currency: "Som ouzbek (UZS)", summary: "Cœur de la Route de la Soie, l'Ouzbékistan abrite Samarcande et Boukhara, joyaux de l'architecture islamique médiévale qui furent parmi les villes les plus importantes du monde entre le VIIe et le XVe siècles. Timur (Tamerlan), né à Shakhrisabz, a fait de Samarcande la capitale de son empire au XIVe siècle. Indépendant de l'URSS depuis 1991." },
  "vn": { population: "98 millions", languages: "Vietnamien", currency: "Đồng (VND)", summary: "Le Viêt Nam a résisté à des siècles d'occupation chinoise, puis à la colonisation française, et a finalement vaincu la superpuissance américaine lors de la guerre du Viêt Nam (1955–1975). Les réformes du Doi Moi (1986) ont ouvert l'économie et propulsé le pays dans une croissance parmi les plus rapides d'Asie. Halong Bay, avec ses 1 600 îlots calcaires, est l'un des plus beaux paysages naturels du monde." },
  "ye": { population: "34 millions", languages: "Arabe", currency: "Rial yéménite (YER)", summary: "Berceau de l'antique royaume de Saba (reine de Saba) et carrefour des routes d'encens millénaires, le Yémen est l'un des berceaux de la civilisation arabe. Depuis 2015, il est ravagé par une guerre civile impliquant une coalition menée par l'Arabie saoudite, provoquant ce que l'ONU a qualifié de pire crise humanitaire du monde, avec des millions de personnes au bord de la famine." },

  // ===== EUROPE =====
  "al": { population: "2,8 millions", languages: "Albanais", currency: "Lek (ALL)", summary: "L'Albanie fut, sous Enver Hoxha (1944–1985), le seul pays communiste à avoir officiellement aboli la religion et déclaré l'athéisme d'État (1967–1992). Sa transition vers la démocratie fut chaotique : une crise des fonds pyramidaux en 1997 plongea le pays dans une quasi-guerre civile. Elle est candidate à l'adhésion à l'Union européenne depuis 2014." },
  "ad": { population: "78 000", languages: "Catalan", currency: "Euro (EUR)", summary: "Principauté de 468 km² enclavée entre la France et l'Espagne dans les Pyrénées, Andorre est l'un des États les plus petits du monde et l'un des plus riches par habitant. Sans armée depuis le XIVe siècle et quasi sans impôts, elle attire des millions de visiteurs pour son commerce de détail. Sa co-souveraineté unique est partagée entre le président français et l'évêque d'Urgell." },
  "at": { population: "9 millions", languages: "Allemand", currency: "Euro (EUR)", summary: "Berceau de la puissante maison de Habsbourg qui régna sur l'Empire austro-hongrois jusqu'en 1918, l'Autriche est la patrie de Mozart, Schubert, Brahms, Freud, Klimt et Wittgenstein. Vienne fut pendant des siècles la capitale culturelle et intellectuelle de l'Europe. Rattachée à l'Allemagne nazie en 1938 (Anschluss), elle est redevenue une démocratie indépendante en 1955." },
  "by": { population: "9,4 millions", languages: "Biélorusse, Russe", currency: "Rouble biélorusse (BYN)", summary: "Surnommée la « dernière dictature d'Europe », la Biélorussie est dirigée par Alexandre Loukachenko depuis 1994 sans alternance démocratique réelle. La catastrophe nucléaire de Tchernobyl (1986) a contaminé un quart de son territoire. Les élections contestées de 2020 ont déclenché des protestations massives réprimées dans le sang, renforcant l'alliance avec Moscou." },
  "be": { population: "11,6 millions", languages: "Français, Néerlandais, Allemand", currency: "Euro (EUR)", summary: "Siège de l'Union européenne et du quartier général de l'OTAN, la Belgique est au carrefour de l'Europe. Pays fédéral aux tensions communautaires profondes entre Flamands et Wallons, il a connu la plus longue période sans gouvernement de l'histoire (541 jours en 2010–2011). C'est aussi la patrie d'Hergé (Tintin), du surréalisme de Magritte et des célèbres gaufres et chocolats." },
  "ba": { population: "3,3 millions", languages: "Bosnien, Serbe, Croate", currency: "Mark convertible (BAM)", summary: "La Bosnie-Herzégovine a vécu la guerre de Bosnie (1992–1995) avec le siège de Sarajevo — 1 425 jours, le plus long d'une ville dans l'histoire de la guerre moderne. Le massacre de Srebrenica, où 8 000 Bosniaques sont tués par les forces serbes en juillet 1995, a été reconnu comme génocide par la justice internationale. Les accords de Dayton (1995) ont mis fin à la guerre mais créé une structure étatique complexe et fragile." },
  "bg": { population: "6,5 millions", languages: "Bulgare", currency: "Lev (BGN)", summary: "La Bulgarie est le berceau de l'alphabet cyrillique, créé au IXe siècle par les moines bulgares Cyrille et Méthode sur ordre du tsar Boris Ier. Première puissance des Balkans au IXe siècle (premier empire bulgare), elle a été sous domination ottomane pendant 500 ans. Elle a rejoint l'UE en 2007 et est l'État membre le plus pauvre de l'Union." },
  "hr": { population: "4 millions", languages: "Croate", currency: "Euro (EUR)", summary: "La Croatie possède 1 244 îles sur sa côte adriatique et la vieille ville de Dubrovnik (le « joyau de l'Adriatique »), classée au patrimoine de l'UNESCO et décor de la série Game of Thrones. Indépendante de la Yougoslavie en 1991, elle a vécu une guerre douloureuse avec la Serbie. Elle est membre de l'UE depuis 2013 et a adopté l'euro en 2023." },
  "cy": { population: "1,2 million", languages: "Grec, Turc", currency: "Euro (EUR)", summary: "L'île de Chypre est divisée depuis l'invasion turque de 1974 : la partie nord (République turque de Chypre du Nord) n'est reconnue que par la Turquie. Dans la mythologie grecque, c'est l'île natale d'Aphrodite, déesse de l'amour. Chypre a rejoint l'UE en 2004 en étant le seul État membre avec une partie de son territoire sous occupation militaire étrangère." },
  "cz": { population: "10,8 millions", languages: "Tchèque", currency: "Couronne tchèque (CZK)", summary: "La Tchéquie a vécu le « Printemps de Prague » en 1968, période de réformes libérales écrasée par les chars soviétiques. Elle a mis fin au communisme avec la « Révolution de velours » en 1989, pacifique et menée par le dramaturge Václav Havel. En 1993, la Tchécoslovaquie se divise pacifiquement en deux États (« Divorce de velours »). Prague est l'une des plus belles villes médiévales d'Europe." },
  "dk": { population: "5,9 millions", languages: "Danois", currency: "Couronne danoise (DKK)", summary: "Patrie des Vikings qui ont sillonné l'Atlantique nord au IXe–XIe siècle et fondé des colonies en Islande, Groenland et même en Amérique du Nord (Vinland). Le Danemark est régulièrement classé parmi les nations les plus heureuses du monde, avec son concept de « hygge » (bien-être et convivialité). Il exerce une souveraineté sur le Groenland, la plus grande île du monde." },
  "ee": { population: "1,4 million", languages: "Estonien", currency: "Euro (EUR)", summary: "L'Estonie est le pays le plus numérisé du monde : premier État à organiser des élections en ligne (2005), à offrir la résidence numérique (e-residency) aux étrangers et à avoir presque toutes ses administrations en ligne. Berceau de Skype, elle a été sous occupation soviétique de 1940 à 1991. La Révolution chantante — une série de manifestations musicales pacifiques — a joué un rôle clé dans son indépendance." },
  "fi": { population: "5,5 millions", languages: "Finnois, Suédois", currency: "Euro (EUR)", summary: "La Finlande est régulièrement classée premier pays du monde pour le bonheur, la qualité de l'éducation (système PISA) et la confiance institutionnelle. Inventeur du sauna — pratique culturelle centrale — elle abrite aussi la Laponie, patrie du Père Noël selon la tradition. Elle a rejoint l'OTAN en 2023 après l'invasion russe de l'Ukraine, rompant 75 ans de neutralité." },
  "fr": { population: "68 millions", languages: "Français", currency: "Euro (EUR)", summary: "Berceau de la Révolution française (1789) et de la Déclaration des droits de l'homme et du citoyen, la France a profondément influencé la politique mondiale. Première puissance touristique mondiale, elle abrite le musée le plus visité au monde (le Louvre) et la tour Eiffel. La France a bâti le deuxième empire colonial le plus étendu de l'histoire et reste une puissance nucléaire et membre permanent du Conseil de sécurité de l'ONU." },
  "de": { population: "84 millions", languages: "Allemand", currency: "Euro (EUR)", summary: "L'Allemagne a provoqué les deux guerres mondiales et commis la Shoah (extermination de 6 millions de Juifs). Divisée en RFA et RDA après 1945, elle est réunifiée en 1990 après la chute du Mur de Berlin (1989), symbole de la fin de la Guerre froide. Aujourd'hui première économie d'Europe et quatrième mondiale, elle est le moteur industriel du continent avec Volkswagen, BMW, Siemens." },
  "gr": { population: "10,4 millions", languages: "Grec", currency: "Euro (EUR)", summary: "La Grèce est le berceau de la démocratie, de la philosophie occidentale (Socrate, Platon, Aristote) et des Jeux Olympiques antiques. Elle a résisté à l'invasion italienne puis allemande pendant la Seconde Guerre mondiale. La crise de la dette grecque (2010–2018) a mis à rude épreuve la zone euro et imposé des plans d'austérité sévères à la population." },
  "hu": { population: "9,7 millions", languages: "Hongrois (magyar)", currency: "Forint (HUF)", summary: "Le hongrois est l'une des langues européennes les plus éloignées de ses voisines — langue finno-ougrienne venue d'Asie centrale avec les Magyars au IXe siècle. La Hongrie a joué un rôle clé dans l'effondrement du rideau de fer en 1989 en ouvrant sa frontière avec l'Autriche, permettant à des milliers d'Allemands de l'Est de fuir vers l'Ouest. Le Parlement de Budapest est l'un des plus beaux bâtiments gothiques du monde." },
  "is": { population: "370 000", languages: "Islandais", currency: "Couronne islandaise (ISK)", summary: "L'Islande abrite le plus ancien parlement du monde encore en activité (l'Althing, fondé en 930). Sans armée depuis 1869 et avec un niveau de criminalité parmi les plus bas du monde, c'est aussi le premier pays à avoir élu une femme présidente (Vigdís Finnbogadóttir, 1980). Ses paysages volcaniques uniques (geysers, aurores boréales, glaciers) en font une destination touristique de premier plan." },
  "ie": { population: "5,1 millions", languages: "Anglais, Irlandais (gaélique)", currency: "Euro (EUR)", summary: "L'Irlande a subi la Grande Famine (1845–1852), causée en grande partie par les politiques britanniques, qui a tué 1 million de personnes et poussé 2 millions à émigrer. Cette diaspora a profondément marqué les États-Unis (25 millions d'Américains d'origine irlandaise). Patrie de James Joyce, Oscar Wilde et Samuel Beckett, l'Irlande est aussi le siège européen de nombreuses multinationales technologiques (Apple, Google, Meta)." },
  "it": { population: "59 millions", languages: "Italien", currency: "Euro (EUR)", summary: "Berceau de l'Empire romain, qui a unifié le monde méditerranéen pendant cinq siècles, et berceau de la Renaissance (Léonard de Vinci, Michel-Ange, Raphaël, Galilée). L'Italie possède le plus grand nombre de sites classés au patrimoine mondial de l'UNESCO (58). La mode, le design et la gastronomie italiens font partie des marques culturelles les plus influentes du monde." },
  "xk": { population: "1,8 million", languages: "Albanais, Serbe", currency: "Euro (EUR)", summary: "Déclaré indépendant de la Serbie le 17 février 2008, le Kosovo est reconnu par environ 117 pays dont les États-Unis et la majorité des États de l'UE, mais pas par la Russie, la Chine ni la Serbie. Il fut le théâtre des guerres des Balkans dans les années 1990 et du bombardement de l'OTAN sur la Serbie en 1999 pour mettre fin aux violences contre la population albanaise." },
  "lv": { population: "1,8 million", languages: "Letton", currency: "Euro (EUR)", summary: "La Lettonie a été occupée successivement par les Suédois, les Russes, les Allemands et les Soviétiques au cours du XXe siècle. Elle a participé à la Révolution chantante avec ses voisins baltes pour obtenir son indépendance en 1991. Riga, sa capitale, est l'une des plus belles villes d'Europe centrale avec son quartier Art Nouveau exceptionnel." },
  "li": { population: "39 000", languages: "Allemand", currency: "Franc suisse (CHF)", summary: "Sixième plus petit pays du monde (160 km²), le Liechtenstein est l'un des deux pays enclavés dans un pays enclavé (avec l'Ouzbékistan). C'est un des pays les plus riches du monde par habitant, avec un secteur financier offshore florissant. Bizarrerie historique : il a supprimé son armée en 1868 après la guerre austro-prussienne, ne l'a jamais recréée." },
  "lt": { population: "2,8 millions", languages: "Lituanien", currency: "Euro (EUR)", summary: "La Lituanie fut le dernier pays d'Europe à adopter officiellement le christianisme, en 1387. Elle fut aussi la première des républiques soviétiques à déclarer son indépendance en mars 1990, malgré l'intervention militaire soviétique. Vilnius, sa capitale, est considérée comme le centre géographique de l'Europe selon certains calculs géodésiques." },
  "lu": { population: "660 000", languages: "Luxembourgeois, Français, Allemand", currency: "Euro (EUR)", summary: "L'un des pays les plus riches au monde par habitant, le Luxembourg est un centre financier international majeur. Il accueille plusieurs institutions cruciales de l'UE : la Cour de justice, la Cour des comptes et la Banque européenne d'investissement. Grand-Duché sous la maison de Nassau-Weilbourg, c'est l'une des dernières monarchies constitutionnelles d'Europe centrale." },
  "mt": { population: "530 000", languages: "Maltais, Anglais", currency: "Euro (EUR)", summary: "Plus petit État membre de l'UE, Malte possède une des langues les plus uniques d'Europe : le maltais est la seule langue sémitique (dérivée de l'arabe) écrite en alphabet latin. Île stratégique de la Méditerranée centrale, elle a résisté au siège ottoman de 1565 et aux bombardements nazis de la Seconde Guerre mondiale (décorée de la Croix de George). Elle fut pendant des siècles le siège des Chevaliers de l'Ordre de Saint-Jean (Hospitaliers)." },
  "md": { population: "2,6 millions", languages: "Roumain, Russe", currency: "Leu (MDL)", summary: "L'un des pays les plus pauvres d'Europe, la Moldavie est au cœur de tensions géopolitiques entre l'UE et la Russie. La région de Transnistrie, à l'est, a fait sécession en 1990 et bénéficie du soutien militaire et économique russe, constituant un conflit gelé. Malgré sa taille modeste, la Moldavie est l'un des plus grands producteurs de vin au monde per capita." },
  "mc": { population: "36 000", languages: "Français", currency: "Euro (EUR)", summary: "Deuxième plus petit pays du monde (2,08 km²), Monaco est la nation la plus dense de la planète. Connue pour son Grand Prix de Formule 1 — la course de rue la plus célèbre du monde — et son casino de Monte-Carlo, elle est le symbole du luxe et de la fortune. Près de 30 % de sa population est millionnaire, le ratio le plus élevé au monde." },
  "me": { population: "620 000", languages: "Monténégrin, Serbe", currency: "Euro (EUR)", summary: "Le Monténégro, dont le nom signifie « Montagne Noire », est l'un des plus jeunes pays d'Europe, indépendant depuis 2006 après un référendum. Il est membre de l'OTAN depuis 2017. Ses côtes adriatiques et ses parcs naturels (canyon de la Tara, le plus profond d'Europe) en font une destination touristique en plein essor." },
  "nl": { population: "17,9 millions", languages: "Néerlandais", currency: "Euro (EUR)", summary: "Pionniers du commerce mondial au XVIIe siècle (le « Siècle d'Or » néerlandais), les Pays-Bas ont fondé la première multinationale (la Compagnie des Indes orientales) et Amsterdam la première bourse des valeurs du monde. Un quart de leur territoire est sous le niveau de la mer, maintenu grâce à un système de digues et de polders parmi les plus sophistiqués du monde." },
  "mk": { population: "2 millions", languages: "Macédonien, Albanais", currency: "Denar (MKD)", summary: "La Macédoine du Nord est le pays natal d'Alexandre le Grand (356–323 av. J.-C.), roi de Macédoine qui conquit l'un des plus grands empires de l'Antiquité, de la Grèce à l'Inde. Elle a dû changer son nom de « Macédoine » à « Macédoine du Nord » en 2019 pour résoudre un différend avec la Grèce et obtenir son adhésion à l'OTAN. Mère Teresa, icône de la charité, était originaire de Skopje." },
  "no": { population: "5,5 millions", languages: "Norvégien", currency: "Couronne norvégienne (NOK)", summary: "La Norvège est l'un des pays les plus riches et les plus égalitaires du monde, grâce à son fonds souverain alimenté par le pétrole de la mer du Nord (le plus grand au monde). Berceau des Vikings qui ont atteint l'Amérique du Nord (Leif Erikson, vers 1000) cinq siècles avant Colomb. Alfred Nobel, inventeur de la dynamite, a légué sa fortune à la création des Prix Nobel, dont la paix est décernée à Oslo." },
  "pl": { population: "38 millions", languages: "Polonais", currency: "Zloty (PLN)", summary: "La Pologne a disparu de la carte de l'Europe pendant 123 ans (1795–1918), partagée entre la Russie, la Prusse et l'Autriche. Durant la Seconde Guerre mondiale, elle perd 20 % de sa population, dont 3 millions de Juifs dans les camps nazis (Auschwitz-Birkenau). Le syndicat Solidarność, dirigé par Lech Wałęsa, a joué un rôle crucial dans l'effondrement du communisme en Europe." },
  "pt": { population: "10,3 millions", languages: "Portugais", currency: "Euro (EUR)", summary: "Fondateur du premier empire colonial mondial aux XVe–XVIe siècles grâce aux explorations de Vasco de Gama, Magellan et Bartolomeu Dias, le Portugal a laissé la langue portugaise parlée par 260 millions de personnes dans le monde. La révolution des Œillets (1974) a mis fin pacifiquement à la plus longue dictature d'Europe occidentale. Le fado, musique mélancolique empreinte de saudade, est au patrimoine immatériel de l'UNESCO." },
  "ro": { population: "19 millions", languages: "Roumain", currency: "Leu (RON)", summary: "La Roumanie a donné naissance au mythe de Dracula, inspiré du voïvode Vlad l'Empaleur (XVe siècle). Elle a connu le seul soulèvement violent de l'Europe de l'Est en 1989 : la révolution contre Nicolae Ceaușescu, qui a été jugé et exécuté en 24 heures le soir de Noël. La Transylvanie médiévale et les monastères peints de Bucovine font partie des trésors patrimoniaux d'Europe." },
  "ru": { population: "145 millions", languages: "Russe", currency: "Rouble (RUB)", summary: "Plus grand pays du monde (17 millions de km², couvrant 11 fuseaux horaires), la Russie a connu l'empire tsariste, la révolution bolchévique (1917), l'URSS de Staline et la Guerre froide. Elle a lancé la course spatiale (Spoutnik, Gagarine) et rivalise avec les États-Unis pour la domination mondiale. L'invasion de l'Ukraine en 2022 a provoqué les plus lourdes sanctions économiques de l'histoire." },
  "sm": { population: "34 000", languages: "Italien", currency: "Euro (EUR)", summary: "Saint-Marin est la plus ancienne République du monde encore existante, fondée selon la tradition en 301 ap. J.-C. par le maçon chrétien Marinus fuyant les persécutions de Dioclétien. Entièrement enclavé dans l'Italie, c'est aussi l'un des États les plus petits du monde. Il ne s'est jamais laissé envahir ni conquérir de façon permanente au cours de son histoire millénaire." },
  "rs": { population: "6,8 millions", languages: "Serbe", currency: "Dinar serbe (RSD)", summary: "L'assassinat de l'archiduc François-Ferdinand à Sarajevo le 28 juin 1914 par un nationaliste serbe a déclenché la Première Guerre mondiale. La Serbie, cœur de la Yougoslavie fondée en 1918, a vécu l'éclatement de ce pays dans les années 1990 dans une violence extrême. Elle ne reconnaît toujours pas l'indépendance du Kosovo, déclarée en 2008." },
  "sk": { population: "5,5 millions", languages: "Slovaque", currency: "Euro (EUR)", summary: "La Slovaquie s'est pacifiquement séparée de la Tchécoslovaquie le 1er janvier 1993 (le « Divorce de velours »). Elle est membre de l'UE depuis 2004 et a adopté l'euro en 2009. Le pays est parsemé de châteaux médiévaux (il en compte plus de 180, le plus grand nombre par habitant en Europe) et abrite les grottes de glace les plus importantes du continent." },
  "si": { population: "2,1 millions", languages: "Slovène", currency: "Euro (EUR)", summary: "La Slovénie fut le premier pays à se détacher de la Yougoslavie, après une courte guerre d'indépendance de dix jours en juin 1991. Premier pays issu de l'ancienne Yougoslavie à rejoindre l'UE (2004). Le lac de Bled, avec son château médiéval et son île, est l'un des paysages les plus photographiés d'Europe." },
  "es": { population: "47,4 millions", languages: "Espagnol (castillan), Catalan, Basque, Galicien", currency: "Euro (EUR)", summary: "L'Espagne a bâti au XVIe siècle l'un des empires les plus étendus de l'histoire, couvrant les Amériques et les Philippines. Elle a vécu une guerre civile dévastatrice (1936–1939) et la dictature de Francisco Franco jusqu'en 1975. Pays de Cervantes, Goya, Picasso, Dalí et Gaudí, elle accueille chaque année plus de 80 millions de touristes, l'un des chiffres les plus élevés au monde." },
  "se": { population: "10,5 millions", languages: "Suédois", currency: "Couronne suédoise (SEK)", summary: "La Suède est pionnière en matière de protection sociale, de parité et d'égalité des genres. Les Prix Nobel ont été créés par l'inventeur suédois Alfred Nobel en 1895. Après des siècles de guerres nordiques et d'empire suédois, elle maintient une neutralité militaire depuis 200 ans, jusqu'à rejoindre l'OTAN en 2024 après l'invasion russe de l'Ukraine." },
  "ch": { population: "8,7 millions", languages: "Allemand, Français, Italien, Romanche", currency: "Franc suisse (CHF)", summary: "Fondée en 1291, la Suisse est neutre depuis 1815 et n'a pas participé aux deux guerres mondiales. Siège de la Croix-Rouge (fondée par le Genevois Henri Dunant), de nombreuses organisations internationales et du CERN (où le World Wide Web a été inventé par Tim Berners-Lee en 1989). Son secret bancaire légendaire en a fait le premier centre financier mondial pendant des décennies." },
  "ua": { population: "44 millions", languages: "Ukrainien, Russe", currency: "Hryvnia (UAH)", summary: "Berceau de la Rous' de Kiev (IXe siècle), précurseur culturel et politique des États russes et ukrainiens modernes. L'Ukraine est le grenier à blé de l'Europe, l'un des premiers exportateurs mondiaux de céréales. La catastrophe de Tchernobyl (1986) s'est produite sur son territoire. Depuis l'annexion de la Crimée par la Russie (2014) et l'invasion à grande échelle (2022), elle résiste dans une guerre défensive qui a reconfiguré l'ordre sécuritaire européen." },
  "gb": { population: "67 millions", languages: "Anglais", currency: "Livre sterling (GBP)", summary: "Le Royaume-Uni a bâti le plus grand empire de l'histoire (un quart des terres émergées, 400 millions de personnes au pic). Berceau de la Révolution industrielle au XVIIIe siècle, de Shakespeare, Newton, Darwin et des Beatles. Après le Brexit (2016–2020), il a quitté l'Union européenne, marquant une rupture historique avec l'intégration européenne." },
  "va": { population: "800", languages: "Latin, Italien", currency: "Euro (EUR)", summary: "Plus petit État souverain du monde (0,44 km²), la Cité du Vatican est le siège de l'Église catholique romaine et la résidence du pape. Fondée en tant qu'État indépendant par les accords du Latran en 1929, elle gouverne spirituellement 1,3 milliard de catholiques dans le monde. Les Musées du Vatican et la basilique Saint-Pierre sont parmi les plus grands trésors artistiques de l'humanité." },

  // ===== OCÉANIE =====
  "au": { population: "26 millions", languages: "Anglais", currency: "Dollar australien (AUD)", summary: "Sixième plus grand pays du monde, l'Australie est un continent à lui seul. Colonisée par les Britanniques en 1788, elle a vu la quasi-extinction des peuples aborigènes (présents depuis 65 000 ans) par les maladies, les violences et les déplacements. Elle abrite une faune unique au monde (kangourous, koalas, ornithorynques) et la Grande Barrière de Corail, l'écosystème vivant le plus grand du monde." },
  "fj": { population: "930 000", languages: "Fidjien, Hindi, Anglais", currency: "Dollar fidjien (FJD)", summary: "Archipel de 330 îles dans le Pacifique Sud, les Fidji sont réputées pour leurs plages, leurs récifs coralliens et la pratique intensive du rugby (champion olympique de rugby à sept). Indépendantes depuis 1970, elles ont connu plusieurs coups d'État militaires depuis 1987, liés aux tensions entre Fidjiens autochtones et Indo-Fidjiens descendants des travailleurs amenés par les Britanniques." },
  "ki": { population: "120 000", languages: "Gilbertin, Anglais", currency: "Dollar australien (AUD)", summary: "Kiribati est l'une des nations les plus menacées par la montée des eaux avec une élévation maximale de 2 mètres. Seul pays à chevaucher à la fois l'équateur et la ligne de changement de date, ses habitants vivent donc à la fois dans l'hémisphère nord et sud, et les premiers à accueillir le Nouvel An. Le gouvernement négocie l'acquisition de terres au Fiji pour y relocaliser sa population." },
  "mh": { population: "42 000", languages: "Marshallais, Anglais", currency: "Dollar américain (USD)", summary: "Les Îles Marshall ont été le théâtre de la bataille de Kwajalein (1944), l'une des plus sanglantes du Pacifique lors de la Seconde Guerre mondiale. Elles ont subi 67 tests nucléaires américains entre 1946 et 1958 (dont la bombe thermonucléaire Castle Bravo, la plus puissante jamais testée par les États-Unis), contaminant durablement certaines îles et leur population." },
  "fm": { population: "115 000", languages: "Anglais", currency: "Dollar américain (USD)", summary: "La Micronésie est un archipel de plus de 600 îles du Pacifique occidental, sous tutelle américaine jusqu'en 1986. Elle possède le lagon de Chuuk (Truk), un site de plongée légendaire abritant les épaves de navires japonais coulés lors de l'opération américaine Hailstone en 1944. Ses habitants font partie des peuples les plus anciennement implantés dans le Pacifique (3 500 av. J.-C.)." },
  "nr": { population: "10 000", languages: "Nauru, Anglais", currency: "Dollar australien (AUD)", summary: "Plus petit État insulaire du monde (21 km²), Nauru a connu une brève période de richesse extraordinaire grâce aux exportations de phosphate (guano fossilisé) dans les années 1970–80, lui valant le deuxième PIB par habitant au monde. Après l'épuisement des gisements, l'île est devenue l'une des plus pauvres d'Océanie. Le pays abrite aujourd'hui un centre de rétention de demandeurs d'asile pour l'Australie." },
  "nz": { population: "5 millions", languages: "Anglais, Maori", currency: "Dollar néo-zélandais (NZD)", summary: "Peuplée par les Maoris au XIIIe siècle puis colonisée par les Britanniques au XIXe, la Nouvelle-Zélande a été le premier pays au monde à accorder le droit de vote aux femmes (1893). Ses paysages spectaculaires ont servi de décor à la trilogie du Seigneur des Anneaux. Les All Blacks, son équipe nationale de rugby, sont la franchise sportive la plus titrée au monde dans son sport." },
  "pw": { population: "18 000", languages: "Palauais, Anglais", currency: "Dollar américain (USD)", summary: "Palaos est célèbre pour le lac des Méduses (Jellyfish Lake), où évoluent des millions de méduses sans dard, et pour ses sites de plongée parmi les plus beaux du monde. Ce petit archipel du Pacifique occidental a été successivement sous domination espagnole, allemande, japonaise et américaine avant son indépendance en 1994. Il est l'un des premiers pays à avoir créé une réserve marine nationale." },
  "pg": { population: "10 millions", languages: "Tok Pisin, Anglais, Hiri Motu (et 800+ langues)", currency: "Kina (PGK)", summary: "La Papouasie-Nouvelle-Guinée est le pays le plus linguistiquement diversifié du monde, avec plus de 800 langues parlées pour 10 millions d'habitants. Certaines régions de l'intérieur sont restées isolées du reste du monde jusqu'au XXe siècle. Elle abrite certaines des forêts tropicales les plus préservées du monde et une faune extraordinaire (paradisiers, casoars)." },
  "ws": { population: "220 000", languages: "Samoan, Anglais", currency: "Tala (WST)", summary: "Le Samoa est le berceau de la culture polynésienne qui a essaimé dans tout le Pacifique (Hawaï, Nouvelle-Zélande, Tahiti). La tradition du pe'a — le tatouage corporel masculin couvrant les hanches et les cuisses — est l'une des pratiques culturelles les mieux préservées du monde polynésien. Le pays a changé de côté de la ligne de changement de date en 2011 pour se rapprocher économiquement de l'Australie et de la Nouvelle-Zélande." },
  "sb": { population: "720 000", languages: "Pijin, Anglais", currency: "Dollar des Îles Salomon (SBD)", summary: "Les Îles Salomon ont été le théâtre de la bataille de Guadalcanal (août 1942–février 1943), l'un des tournants de la guerre du Pacifique contre le Japon. Cet archipel de plus de 900 îles possède une biodiversité marine exceptionnelle. En 2019, les Îles Salomon ont rompu leurs relations diplomatiques avec Taïwan au profit de la Chine populaire." },
  "to": { population: "100 000", languages: "Tongien, Anglais", currency: "Pa'anga (TOP)", summary: "Tonga est le seul royaume polynésien à n'avoir jamais été pleinement colonisé par une puissance européenne — elle resta un protectorat britannique tout en conservant sa monarchie et ses institutions. Réputé pour ses baleines à bosse (la saison de nage avec les baleines est célèbre) et ses traditions polynésiennes vivaces. Le rugby est un sport national avec une passion qui dépasse de loin la taille du pays." },
  "tv": { population: "11 000", languages: "Tuvaluan, Anglais", currency: "Dollar australien (AUD)", summary: "Quatrième plus petit pays du monde, Tuvalu est parmi les nations les plus menacées par la montée des eaux : son point culminant est à 4,5 mètres. Pour financer son développement, le pays vend son extension internet (.tv) à des chaînes de télévision du monde entier pour plusieurs millions de dollars par an. Le gouvernement envisage une migration totale de sa population vers les Fidji ou l'Australie d'ici 2050." },
  "vu": { population: "330 000", languages: "Bichlamar, Anglais, Français", currency: "Vatu (VUV)", summary: "Vanuatu est un archipel gouverné conjointement par la France et le Royaume-Uni sous forme de condominium de 1906 à 1980 — une situation administrative unique dans l'histoire coloniale. Il abrite des volcans actifs dont le mont Yasur, accessible aux touristes et actif depuis des siècles. Le « land diving » (plongeon rituel avec des lianes végétales) pratiqué sur l'île de Pentecôte est l'ancêtre direct du saut à l'élastique."  }
};
